import {mountCourseMap} from './course-map.js';
import {renderLessonDetail} from './lesson-one-view.js';
import {chapters} from './content.js';
import {demos} from './engine.js';
import {renderFrame} from './renderers.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let chapter=chapters[0],tab='learn',frames=[],pos=0,timer=null,demoId='avl';
const cache=new Map();let diagramActualSize=false;
$('#chapters').innerHTML=chapters.map((c,i)=>`${!i||c.group!==chapters[i-1].group?`<div class="group">${c.group}</div>`:''}<a href="#${c.id}" data-chapter="${c.id}"><em>${c.n}</em>${c.title}</a>`).join('');
$('#menu').onclick=()=>document.body.classList.toggle('menu-open');
function stop(){clearInterval(timer);timer=null;if($('#play'))$('#play').textContent='▶ 自动播放'}
function navigate(){stop();document.querySelector('[data-course-map]')?.classList.remove('active');const [id='avl',requested]= (location.hash.slice(1)||'avl').split('/');document.body.classList.remove('menu-open');if(id==='mindmap'){tab='mindmap';mountCourseMap(chapters,demos,requested);window.scrollTo(0,0);return}if(id==='sources'||id==='overview'){renderReference(id);window.scrollTo(0,0);return}chapter=chapters.find(c=>c.id===id)||chapters[0];tab=requested==='implementation'&&chapter.implementation?'implementation':'learn';demoId=chapter.demos.includes(requested)?requested:chapter.demos[0];render();window.scrollTo(0,0)}
function render(){document.title=`${chapter.title} · ADS 算法研习室`;$('#breadcrumb').textContent=chapter.title;document.querySelectorAll('[data-chapter]').forEach(a=>a.classList.toggle('active',a.dataset.chapter===chapter.id));$('#main').innerHTML=`<div class="eyebrow">CHAPTER ${chapter.n} / ${chapter.group.split('·')[1]||'课程导航'}</div><h1>${chapter.title}<span class="english">${chapter.en}</span></h1><p class="intro">${chapter.desc}</p><div class="meta"><span>课件 ${esc(chapter.file)} · p.${chapter.pages}</span><span>${chapter.prereq}</span></div><a class="chapter-map-link" href="#mindmap/${chapter.id}">查看本章在课程地图中的位置 ↗</a><div class="tabs" role="tablist" aria-label="章节内容">${[['learn','知识与实验'],...(chapter.implementation?[['implementation','实现细节']]:[]),['proof','推导与证明'],['extend','扩展与辨析'],['practice','思考与练习']].map(([id,label])=>`<button role="tab" aria-selected="${tab===id}" id="tab-${id}" class="${tab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div><div id="panel" role="tabpanel" aria-labelledby="tab-${tab}"></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{stop();tab=b.dataset.tab;render()});renderPanel()}
function renderPanel(){let html='';if(tab==='learn'){html=`${chapter.learningPath?`<div class="lesson-path">${chapter.learningPath.map(([id,title,desc])=>`<a href="#${chapter.id}/${id}"><b>${title}</b><span>${desc}</span></a>`).join('')}</div>`:''}<div class="section-title"><h2>算法实验室 <small>Algorithm lab</small></h2><span class="live-label">可操作 · 可回放</span></div><section class="lab" aria-label="交互演示"><div class="lab-toolbar"><label>演示主题<select id="demo">${chapter.demos.map(id=>`<option value="${id}">${demos[id]?.title||id}</option>`).join('')}</select></label><label class="wide"><span id="input-label">输入序列</span><input id="input" aria-label="演示输入"></label><button id="run" class="primary">生成演示 ↗</button></div><div id="presets" class="lesson-presets"></div><div class="lab-error" id="error" role="alert"></div><div id="checkpoints" class="lesson-checkpoints"></div><div class="lab-grid"><div id="stage" class="stage" aria-label="算法状态图"></div><aside class="trace"><h3>执行过程</h3><span class="step-number" id="step-number"></span><p id="message" aria-live="polite"></p><dl id="metrics"></dl></aside></div><div class="player"><button id="reset" aria-label="回到初始状态">↺</button><button id="prev" aria-label="上一步">◀</button><button id="play" class="primary">▶ 自动播放</button><button id="next" aria-label="下一步">▶|</button><input id="seek" type="range" min="0" value="0" aria-label="演示步骤"><label>速度 <select id="speed"><option value="1100">慢</option><option value="650" selected>标准</option><option value="220">快</option></select></label></div></section><div class="legend"><span><i></i>当前操作 / 选中状态</span><span>↺ 从头回放 · 修改输入生成新过程</span></div><div id="lab-detail"></div><div class="reading-grid"><article class="article"><h2>核心知识</h2>${chapter.concepts.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}<h3>算法步骤</h3><pre id="code" class="code"></pre></article><aside class="aside-card"><h3>复杂度与前提</h3><p>${chapter.cost}</p><h3>学习这章时</h3><ul><li>先观察一次完整执行。</li><li>改变输入，寻找边界情况。</li><li>再用不变量解释每一步。</li></ul><h3>课件依据</h3><p>${chapter.file}<br>第 ${chapter.pages} 页</p></aside></div>`}else if(tab==='implementation')html=`<article class="article implementation"><p>从可运行的基本实现出发，把动画中的局部操作对应到真实代码。</p>${chapter.implementation.map(s=>`<section><h3>${s.title}</h3><p>${s.text}</p>${s.code?`<pre class="code">${esc(s.code)}</pre>`:''}</section>`).join('')}</article>`;else if(tab==='proof')html=`<article class="article">${chapter.proofs.map((p,i)=>`<section class="proof"><span class="tag">PROOF ${String(i+1).padStart(2,'0')} · ${p.method}</span><h3>${p.title}</h3><p>${p.claim}</p><ol>${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="formula">${p.formula||''}</div><div class="qed">证毕 □</div></section>`).join('')}</article>`;else if(tab==='extend')html=`<article class="article">${chapter.extensions.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}${chapter.correction?`<div class="note"><b>课件勘误与适用条件</b><br>${chapter.correction}</div>`:''}${(chapter.refs||[]).map(([title,url])=>`<p>延伸阅读：<a href="${url}" target="_blank" rel="noopener">${title} ↗</a></p>`).join('')}</article>`;else html=`<article class="article"><p>先独立推演，再展开参考解答。练习用于检验本章的定义、边界与证明。</p>${chapter.quiz.map(([q,a],i)=>`<details><summary>${i+1}. ${q}</summary><p>${a}</p></details>`).join('')}</article>`;const i=chapters.indexOf(chapter);$('#panel').innerHTML=html+`<div class="chapter-nav">${i?`<a href="#${chapters[i-1].id}">← ${chapters[i-1].title}</a>`:'<span></span>'}${i<chapters.length-1?`<a href="#${chapters[i+1].id}">${chapters[i+1].title} →</a>`:''}</div>`;if(tab==='learn')setupLab()}
function setupLab(){$('#demo').value=demoId;$('#demo').onchange=e=>{demoId=e.target.value;history.replaceState(null,'','#'+chapter.id+'/'+demoId);loadDemo()};$('#run').onclick=run;$('#input').onkeydown=e=>{if(e.key==='Enter')run()};$('#prev').onclick=()=>{stop();pos=Math.max(0,pos-1);paint()};$('#next').onclick=()=>{stop();pos=Math.min(frames.length-1,pos+1);paint()};$('#reset').onclick=()=>{stop();pos=0;paint()};$('#seek').oninput=e=>{stop();pos=+e.target.value;paint()};$('#play').onclick=()=>{if(timer){stop();return}if(pos===frames.length-1)pos=0;$('#play').textContent='Ⅱ 暂停';timer=setInterval(()=>{pos++;paint();if(pos>=frames.length-1)stop()},+$('#speed').value)};$('#speed').onchange=()=>{if(timer){stop();$('#play').click()}};loadDemo()}
function loadDemo(){stop();const d=demos[demoId],saved=cache.get(demoId);$('#input-label').textContent=d.label;$('#input').value=saved?.input??d.default;$('#code').textContent=d.code;$('#presets').innerHTML=d.presets?`<b>教学案例</b><div>${d.presets.map((p,i)=>`<button data-preset="${i}">${esc(p.label)}</button>`).join('')}</div><p id="preset-why"></p>`:'';document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const p=d.presets[+b.dataset.preset];$('#input').value=p.input;run()});run();if(saved){pos=Math.min(saved.pos,frames.length-1);paint()}else if(demoId==='avl'){pos=Math.max(0,frames.findIndex(f=>f.msg==='插入 28 完成。'));paint()}}
function run(){stop();try{const d=demos[demoId];const raw=$('#input').value.trim();if(!raw)throw Error('请输入演示数据。');let data=d.parse?d.parse(raw):raw.split(/[,，\s]+/).map(Number);if(!d.parse&&(data.length>24||data.some(x=>!Number.isSafeInteger(x)||Math.abs(x)>999)))throw Error('请输入最多 24 个 −999 到 999 之间的整数。');frames=d.run(data);if(!frames.length)throw Error('该输入没有可展示的步骤。');pos=0;$('#error').textContent='';if($('#preset-why')){$('#preset-why').textContent=d.presets.find(p=>p.input.replace(/\s/g,'')===raw.replace(/\s/g,''))?.why||'自定义案例：逐步观察关键分支与不变量。';document.querySelectorAll('[data-preset]').forEach(b=>b.setAttribute('aria-pressed',String(d.presets[+b.dataset.preset].input.replace(/\s/g,'')===raw.replace(/\s/g,''))))};$('#seek').max=frames.length-1;$('#checkpoints').innerHTML=frames[0].teaching?`<label for="checkpoint">关键步骤</label><select id="checkpoint">${frames.map((f,i)=>f.complete||f.teaching.proof||f.teaching.decision||['准备','开始','逻辑替换','分离并删除根','验证 Join 前提'].includes(f.teaching.phase)?`<option value="${i}">${i+1}. ${esc(f.msg)}</option>`:'').join('')}</select>`:'';if($('#checkpoint'))$('#checkpoint').onchange=e=>{stop();pos=+e.target.value;paint()};paint()}catch(e){$('#error').textContent=e.message}}
function paint(){const f=frames[pos];if(!f)return;const oldNodes=new Map([...$('#stage').querySelectorAll('[data-node]')].map(n=>[n.dataset.panel+':'+n.dataset.node,{x:+n.dataset.x,y:+n.dataset.y}]));$('#stage').innerHTML=(f.teaching?`<div class="diagram-tools"><span>稳定编号追踪同一节点 · 两树可独立滚动</span><button id="diagram-size" aria-pressed="${diagramActualSize}">${diagramActualSize?'适应画布':'原始字号'}</button></div>`:'')+renderFrame(f);$('#stage').classList.toggle('actual-size',diagramActualSize);if($('#diagram-size'))$('#diagram-size').onclick=()=>{diagramActualSize=!diagramActualSize;paint()};if($('#checkpoint')){const stops=[...$('#checkpoint').options].map(o=>+o.value);$('#checkpoint').value=stops.filter(i=>i<=pos).at(-1)??stops[0]};$('#stage').classList.toggle('lesson-stage',!!f.teaching);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)for(const n of $('#stage').querySelectorAll('[data-node]')){const p=oldNodes.get(n.dataset.panel+':'+n.dataset.node);if(p&&(p.x!==+n.dataset.x||p.y!==+n.dataset.y))n.animate([{transform:`translate(${p.x}px,${p.y}px)`},{transform:`translate(${n.dataset.x}px,${n.dataset.y}px)`}],{duration:280,easing:'ease-out'})}$('#lab-detail').innerHTML=renderLessonDetail(f);$('#message').textContent=f.msg;$('#step-number').textContent=`STEP ${String(pos+1).padStart(2,'0')} / ${frames.length}`;$('#metrics').innerHTML=Object.entries(f.metrics||{}).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('');$('#seek').value=pos;$('#prev').disabled=pos===0;$('#next').disabled=pos===frames.length-1;cache.set(demoId,{input:$('#input').value,pos})}
function renderReference(id){document.querySelectorAll('[data-chapter]').forEach(a=>a.classList.remove('active'));const overview=id==='overview';$('#breadcrumb').textContent=overview?'课程总览':'课件与参考资料';document.title=`${$('#breadcrumb').textContent} · ADS 算法研习室`;const proofs=chapters.reduce((n,c)=>n+c.proofs.length,0);let html=`<div class="eyebrow">ADS / ${overview?'LEARNING GUIDE':'SOURCE NOTES'}</div><h1>${overview?'高级数据结构与算法分析':'课件与参考资料'}</h1><p class="intro">以 16 份 Student Slides（285 页）为知识主线，组织为 15 个专题章节。讲义补充定义、推导、反例与适用条件，动态实验用于观察算法状态。</p>`;if(overview){html+=`<a class="map-entry" href="#mindmap"><b>打开完整课程知识地图 ↗</b><span>四条主线 · 关键问题与难点 · 应用案例 · 研究前沿 · 可导出完整纲要</span></a><div class="course-stats"><div><b>15</b><span>专题章节</span></div><div><b>${Object.keys(demos).length}</b><span>可操作实验</span></div><div><b>${proofs}</b><span>分步骤证明</span></div><div><b>${chapters.reduce((n,c)=>n+c.quiz.length,0)}</b><span>带解答练习</span></div></div><article class="article"><h2>如何使用</h2><p>每章先运行默认案例，再修改输入测试边界。查看“推导与证明”解释关键步骤，随后阅读“扩展与辨析”，最后独立完成练习。输入和回放位置在当前页面会话中保留；刷新后回到默认案例。</p><div class="formula">BST / 递归 → 平衡树与可合并堆 → 分治、回溯、DP、贪心\n归纳 / 渐近分析 → 摊还分析 → 随机算法、并行与外存模型\n图论 / 逻辑 → NP 完全性 → 近似算法与局部搜索</div><h2>课程目录</h2><div class="toc-overview">${chapters.map(c=>`<a href="#${c.id}"><b>${c.n} · ${c.title}</b><small>${c.demos.map(d=>demos[d].title).join(' / ')}</small></a>`).join('')}</div></article>`}else{const refs=[...new Map(chapters.flatMap(c=>c.refs||[]).map(r=>[r[1],r])).values()];html+=`<article class="article"><h2>内容来源与约定</h2><p>课程主题与案例来自本地 Materials / Student Slides。ADS00.ppt（13 页）为课程介绍；其余 15 份课件对应下表。网站没有复制课程群号、学生信息、作业绑定信息或过去学期的评分时间安排。</p><p>各章“核心知识”按课件重新组织；分步骤证明、程序化实验与补充辨析为网站扩写。浏览器显示所有中间状态以便教学，快照存储、图形布局和某些直观容器实现的成本不等同于讲义讨论的理想算法成本。比如可视化重算高度、按值展示最小堆、外排扫描表头，会有额外工作；复杂度结论均以章节声明的标准实现和计算模型为准。</p><p>默认树结构按集合语义处理重复键；数组排序允许重复。整数输入有规模限制，便于逐步演示。图顶点从 0 编号，矩阵链名称与皇后行列说明从 1 编号。红黑树和 B+ 树当前演示插入与查找，删除机制在讲义中解释；其他实验的具体范围见下表。</p><div class="table-wrap"><table><thead><tr><th>章节 / 课件</th><th>页码依据</th><th>交互覆盖</th></tr></thead><tbody>${chapters.map(c=>`<tr><td><a href="#${c.id}">${c.n} ${c.title}</a><br><small>${c.file}</small></td><td>${c.pages}</td><td>${c.demos.map(d=>demos[d].title).join('<br>')}</td></tr>`).join('')}</tbody></table></div><h2>勘误与解释范围</h2>${chapters.filter(c=>c.correction).map(c=>`<div class="source-item"><b><a href="#${c.id}">${c.n} ${c.title}</a></b><p>${c.correction}</p></div>`).join('')}<p>课程地图的近期论文、研究状态和应用资料见 <a href="#mindmap/research">开放问题与前沿</a>，案例出处见 <a href="#mindmap/cases">应用案例</a>。核查日期单独标注。</p><h2 style="margin-top:30px">作者教材与学术资料</h2><p>下列原始教材、作者论文或大学课程资料用于交叉核对与延伸阅读。课件已有教材引用包括 Weiss、CLRS、Kleinberg–Tardos 与 Vishkin；网站不提供这些教材的未经授权复制件。</p>${refs.map(([title,url])=>`<div class="source-item"><a href="${url}" target="_blank" rel="noopener">${title} ↗</a></div>`).join('')}<p><small>课件勘误基于当前提供版本中的文字与本网站明确写出的数学约定。历史研究进展未被当作当前定论重述。</small></p></article>`}$('#main').innerHTML=html}
$('#chapters').insertAdjacentHTML('afterbegin','<a href="#mindmap" data-course-map><em>◎</em>完整课程知识地图</a>');
$('#chapters').insertAdjacentHTML('afterbegin','<a href="#overview"><em>00</em>课程总览与学习路径</a>');
$('#chapters').insertAdjacentHTML('beforeend','<div class="group">REFERENCE</div><a href="#sources"><em>↗</em>课件依据与勘误</a>');
window.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('menu-open');if(e.target.getAttribute?.('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[role=tab]')],i=tabs.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();document.querySelectorAll('[role=tab]')[next].focus()}});
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const definitions=[{name:'read_algorithm_state',title:'读取课程实验状态',description:'读取当前章节、实验与步骤，无副作用。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({chapter:chapter.id,tab,demo:demoId,step:pos,total:frames.length,message:frames[pos]?.msg})},{name:'run_algorithm_demo',title:'运行算法实验',description:'验证输入并在页面中打开指定算法的动态实验，从第一步开始。',inputSchema:{type:'object',properties:{demo:{type:'string',enum:Object.keys(demos)},input:{type:'string'}},required:['demo','input'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.input!=='string'||!input.input.trim()||!Object.hasOwn(demos,input.demo))throw Error('需要合法的 demo 与输入字符串。');const d=demos[input.demo];d.run(d.parse(input.input.trim()));stop();chapter=chapters.find(c=>c.demos.includes(input.demo));demoId=input.demo;tab='learn';cache.set(demoId,{input:input.input,pos:0});history.replaceState(null,'','#'+chapter.id);render();return{chapter:chapter.id,demo:demoId,steps:frames.length,message:frames[0].msg}}},{name:'seek_algorithm_step',title:'跳转演示步骤',description:'跳转到当前算法实验的某一步（从 0 编号），并暂停播放。',inputSchema:{type:'object',properties:{step:{type:'integer',minimum:0}},required:['step'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Number.isInteger(input?.step)||input.step<0||input.step>=frames.length||!$('#stage'))throw Error('步骤越界，或当前没有打开实验。');stop();pos=input.step;paint();return{step:pos,message:frames[pos].msg,metrics:frames[pos].metrics}}}];for(const tool of definitions){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}}
window.addEventListener('hashchange',navigate);navigate();
